function wakeMinutes(bedMin, cycles){ return (bedMin + cycles*90 + 15) % 1440; } // +15min 入睡
function sleepDebt(nights){ // nights: [{need, actual}], 单位小时
  var d=0; for(var i=0;i<nights.length;i++){ d += (nights[i].need||0) - (nights[i].actual||0); } return d;
}
function fmtMin(m){ m=((m%1440)+1440)%1440; var h=Math.floor(m/60), mm=m%60; return (h<10?'0':'')+h+':'+(mm<10?'0':'')+mm; }
var EXPORTS={wakeMinutes:wakeMinutes, sleepDebt:sleepDebt, fmtMin:fmtMin};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SleepForgePure = EXPORTS; }
